 .skill-group { min-width: 0; padding: 17px 0; border-top: 1px solid var(--line); }
 .skill-group h3 { margin: 0 0 15px; color: var(--green); font: 500 14px var(--display); }
 .skill-row { display: grid; grid-template-columns: minmax(110px, 1fr) minmax(65px, 1.5fr) 34px; align-items: center; gap: 10px; margin: 10px 0; }
 .skill-name { overflow: hidden; color: #c0c6bf; font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
 .skill-bar { height: 5px; overflow: hidden; background: #202621; }
 .skill-fill { display: block; width: var(--skill-level); height: 100%; background: var(--green-dim); animation: skill-fill-in .7s ease both; }
 .skill-value { color: var(--muted); font-size: 8px; text-align: right; }
