 .experience-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 34px; }
 .grid-label { display: flex; align-items: center; gap: 9px; margin: 0 0 13px; color: var(--paper); font: 500 12px var(--mono); }
 .grid-label span { width: 15px; height: 1px; background: var(--green); }
 .card-list { display: grid; gap: 11px; }
 .experience-card, .project-card { display: block; min-width: 0; padding: 16px; border: 1px solid var(--line); border-left: 2px solid var(--green-dim); background: rgba(17, 21, 18, .76); color: var(--paper); }
 a.project-card { transition: border-color .18s ease, background .18s ease; }
